# Use the reviewed player descriptions for items updated by rc.27.
reviewed = json.loads((R/'catalog/player_tooltips.json').read_text())
for key in ('malefic_gun', 'legacy_windtalker', 'feather_of_heaven', 'wind_of_nature', 'vampire_mallet', 'magic_blade', 'rose_gold_meteor', 'ice_queen_wand', 'mystic_container', 'queens_wings', 'star_shard', 'war_axe', 'starlium_scythe', 'shadow_twinblades'):
 mechanics[key] = reviewed[key]['base']
