(R/'catalog/mechanics.json').write_text(json.dumps(mechanics,indent=2)+'\n')
old=json.loads((R/'text/item.i18n').read_text());en={k:v for k,v in old['en'].items() if k in ['category','info','tier_header','related','tier','spec']}
en['tier_header']={'1':'Basic Components','2':'Advanced Components','3':'Forged Components' ,'4':'Finished Equipment','5':'Mythical Equipment','boots':'Boots'}
player=json.loads((R/'catalog/player_tooltips.json').read_text())
assert set(player)=={s['key'] for s in specs}, 'Every equipment entry needs reviewed player copy'
for s in specs:
 def description(form):
  desc=player[s['key']][form]
  if s['stats'].get('flat_physical_penetration'):desc+=('\n' if desc else '')+'+'+str(s['stats']['flat_physical_penetration'])+' Physical Penetration.'
  if s['stats'].get('flat_magic_penetration'):desc+=('\n' if desc else '')+'+'+str(s['stats']['flat_magic_penetration'])+' Magic Penetration.'
  if s.get('legacy'):desc='Retired equipment.\n'+desc
  return '\n'+colour_tooltip(desc) if desc else ''
 en[s['key']]={'name':('Legacy ' if s.get('legacy') else '')+s['name'],'option':description('base')}
 if s['mythical']:en['mythical_'+s['key']]={'name':('Legacy ' if s.get('legacy') else '')+'Mythical '+s['name'],'option':description('mythical')}
stock_keys=['ironsword','dagger','steel_armor','mystic_cloak','arcane_crystal','vital_orb','soldiers_longsword','wind_dagger','gatekeepers_armor','night_hood','spirit_crystal','hardened_heart','ruinous_blade','twin_stormblade','black_knights_heavy_plate','dusk_raven','staff_of_rapture','ring_of_reincarnation','conquerors_greatsword','thunderclaw','eternal_iron_plate','souls_edge','angels_fang','hourglass_of_eternity','warlords_final_judgement','storm_sovereign','impregnable_fortress','veil_of_annihilation','prophet_of_the_abyss','giants_horn_shard']
for key in stock_keys:en[key]={'name':'[TFM2] '+key.replace('_',' ').title()}
# English fallback entries for all supported upstream locales; no false translated claims.
(R/'text/item.i18n').write_text(json.dumps({locale:en for locale in old},ensure_ascii=False,indent=2)+'\n')
u=json.loads((R/'text/ui.i18n').read_text())
def strings(v):
 if isinstance(v,str):return v.replace('Radiants','Mythicals').replace('Radiant','Mythical').replace('Legendary','Finished').replace('radiants','mythicals').replace('radiant','mythical')
 if isinstance(v,dict):return {k:strings(w) for k,w in v.items()}
 return v
u=strings(u)
def fallback_tiers(local, english):
 for k,v in english.items():
  if k.startswith('tier_') or 'item_rules' in k: local[k]=v
  elif isinstance(v,dict) and isinstance(local.get(k),dict): fallback_tiers(local[k],v)
for loc in u:fallback_tiers(u[loc],u['en'])
# Ensure rules labels use English fallback rather than stale translated Radiant wording.
for loc in u:
 for k,v in u['en']['builds'].items():
  if 'item_rules' in k or k.startswith('tier_'):u[loc]['builds'][k]=v
(R/'text/ui.i18n').write_text(json.dumps(u,ensure_ascii=False,indent=2)+'\n')
lines=['# Implemented equipment behavior','', 'All numbers describe this TFM2 adaptation, not current official MLBB patch values. Mythical is a custom upgrade tier. See README for calibration and limitations.','']
for s in specs:lines+=['## '+s['name'],'',f'Native tier {s["tier"]}; base price {s["price"]}; stats: `{json.dumps(s["stats"],sort_keys=True)}`.','',mechanics.get(s['key'],'Stats only; no scripted passive.'),'']
(R/'docs/EQUIPMENT_BEHAVIOR.md').write_text('\n'.join(lines))
